ALTER TABLE public.fast_enrollments ADD COLUMN store_id uuid REFERENCES public.stores(id), ADD COLUMN activated_at timestamptz;
CREATE UNIQUE INDEX fast_enrollments_store_id_key ON public.fast_enrollments(store_id) WHERE store_id IS NOT NULL;
GRANT SELECT (store_id, activated_at) ON public.fast_enrollments TO authenticated;
CREATE TABLE public.sticker_invoice_guards (invoice_id uuid PRIMARY KEY REFERENCES public.invoices(id), excluded_txids text[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.sticker_invoice_guards TO service_role;
ALTER TABLE public.sticker_invoice_guards ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.sticker_credit_claims (tx_hash text PRIMARY KEY, invoice_id uuid NOT NULL REFERENCES public.invoices(id), created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.sticker_credit_claims TO service_role;
ALTER TABLE public.sticker_credit_claims ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.get_public_sticker(_code text) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT jsonb_build_object('code',f.coin_id,'name',s.name,'store_id',s.id,'giving',s.egiving_enabled,'active',true) FROM fast_enrollments f JOIN stores s ON s.id=f.store_id WHERE f.coin_id=_code AND f.status='activated' AND s.deactivated_at IS NULL $$;
REVOKE ALL ON FUNCTION public.get_public_sticker(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_public_sticker(text) TO anon, authenticated, service_role;
CREATE OR REPLACE FUNCTION public.activate_fast_sticker(_id uuid, _manager uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE f fast_enrollments%ROWTYPE; sid uuid; BEGIN SELECT * INTO f FROM fast_enrollments WHERE id=_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Enrollment not found'; END IF; IF f.status='activated' THEN RETURN f.store_id; END IF; IF f.status <> 'pending' THEN RAISE EXCEPTION 'Enrollment is not pending'; END IF; IF substring(f.tsd_address from 2 for 6) <> f.coin_id THEN RAISE EXCEPTION 'Coin code mismatch'; END IF;
INSERT INTO stores(owner_id,name,fiat_currency,business_address,business_city,business_region,business_country,business_postal_code,business_category,business_phone,egiving_enabled,listing_visibility) VALUES (_manager,f.business_name,'USD',f.street,f.city,f.region,f.country,f.postal_code,f.category,f.phone,f.egiving_opt_in,'hidden') RETURNING id INTO sid;
INSERT INTO chain_configs(store_id,chain,xpub_or_address,xpub,enabled,stables) VALUES (sid,'txc',f.tsd_address,NULL,true,ARRAY['TSD']);
INSERT INTO store_notification_prefs(store_id,user_id,enabled,email_enabled,email_address,telegram_enabled,events) VALUES (sid,_manager,true,true,f.email,false,'{"invoice_paid":true,"invoice_underpaid":true,"invoice_overpaid":true}'::jsonb);
UPDATE fast_enrollments SET store_id=sid,status='activated',activated_at=now() WHERE id=_id; RETURN sid; END $$;
REVOKE ALL ON FUNCTION public.activate_fast_sticker(uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.activate_fast_sticker(uuid,uuid) TO service_role;